CREATE OR REPLACE FUNCTION app_private.assert_payment_session()
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=auth.uid(); claims jsonb:=auth.jwt(); sid uuid;
BEGIN
 IF actor IS NULL OR claims->>'role' IS DISTINCT FROM 'authenticated'
    OR coalesce(claims->>'is_anonymous','false') <> 'false' THEN
  RAISE EXCEPTION 'A current signed-in session is required' USING ERRCODE='42501';
 END IF;
 BEGIN sid := nullif(claims->>'session_id','')::uuid;
 EXCEPTION WHEN invalid_text_representation THEN sid:=NULL;
 END;
 IF sid IS NULL OR NOT EXISTS (
  SELECT 1 FROM auth.sessions s JOIN auth.users u ON u.id=s.user_id
  WHERE s.id=sid AND s.user_id=actor AND u.deleted_at IS NULL
    AND (u.banned_until IS NULL OR u.banned_until <= now())
    AND (s.not_after IS NULL OR s.not_after > now())
 ) OR EXISTS (
  SELECT 1 FROM app_private.account_deletion_requests r
  WHERE r.user_id=actor AND r.status='completed'
 ) THEN
  RAISE EXCEPTION 'A current signed-in session is required' USING ERRCODE='42501';
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.agent_payout_center()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'app_private, public'
AS $function$
declare v_ref app_private.referrers; v_prof app_private.agent_profiles;
        v_payable numeric; v_accrued numeric; v_paid numeric; v_next timestamptz;
        v_reasons jsonb := '[]'::jsonb; v_min numeric := 100;
        v_pair boolean; v_has_carrier boolean; v_missing text;
begin
  perform app_private.assert_payment_session();
  v_ref := app_private.agent_referrer_for(auth.uid());
  if v_ref.id is null then return jsonb_build_object('has_code', false); end if;
  select * into v_prof from app_private.agent_profiles where user_id = auth.uid();
  select coalesce(sum(amount) filter (where status = 'payable'), 0),
         coalesce(sum(amount) filter (where status = 'accrued'), 0),
         coalesce(sum(amount) filter (where status = 'paid'), 0),
         min(payable_at) filter (where status = 'accrued')
    into v_payable, v_accrued, v_paid, v_next
    from app_private.referral_commissions where referrer_id = v_ref.id;
  if v_prof.status is distinct from 'approved' then
    v_reasons := v_reasons || jsonb_build_object('icon','🛡','text','Verification incomplete — payouts unlock after LoadBoot approves your agent application (Get Verified tab).');
  end if;
  if coalesce(v_prof.payout_method,'') = '' then
    v_reasons := v_reasons || jsonb_build_object('icon','🏦','text','No payout account on file — add your bank/Payoneer in Get Verified step 3.');
  end if;
  -- bl_agent_0307: name the pair-hold instead of letting the clearing date pass in silence.
  if v_prof.status = 'approved' and v_accrued > 0 then
    v_pair := app_private.referrer_pair_active(v_ref.id);
    if not v_pair then
      select exists (select 1 from app_private.referral_edges e join public.organizations o on o.id = e.child_org
                      where e.referrer_id = v_ref.id and o.kind = 'carrier') into v_has_carrier;
      v_missing := case when not v_has_carrier then 'a CARRIER (any trucking company)' else 'the FREIGHT side (a broker or shipper — or post a load yourself)' end;
      v_reasons := v_reasons || jsonb_build_object('icon','🔗',
        'text','$' || v_accrued || ' is earned and safe, but held — your chain is not paired yet. Bring ' || v_missing || ' through your link and it releases on its normal 15-day schedule. Nothing you earned is ever lost.');
    end if;
  end if;
  if v_payable < v_min then
    v_reasons := v_reasons || jsonb_build_object('icon','💵','text','Payable balance $' || v_payable || ' is below the $' || v_min || ' minimum' ||
      case when v_accrued > 0 then ' — $' || v_accrued || ' more is clearing' || case when v_next is not null then ' (next release ' || to_char(v_next,'Mon DD') || ')' else '' end else '' end || '.');
  end if;
  if exists (select 1 from app_private.referral_payout_requests r where r.referrer_id = v_ref.id and r.status in ('requested','approved')) then
    v_reasons := v_reasons || jsonb_build_object('icon','⏳','text','A payout request is already in progress — track it below.');
  end if;
  return jsonb_build_object(
    'has_code', true,
    'payable', v_payable, 'accrued', v_accrued, 'paid', v_paid,
    'next_clearing', v_next, 'min_required', v_min,
    'eligible', (v_prof.status = 'approved' and coalesce(v_prof.payout_method,'') <> '' and v_payable >= v_min
                 and not exists (select 1 from app_private.referral_payout_requests r where r.referrer_id = v_ref.id and r.status in ('requested','approved'))),
    'reasons', v_reasons,
    'bank', case when v_prof.user_id is null then null else jsonb_build_object(
      'method', v_prof.payout_method,
      'title', v_prof.payout_details->>'account_title',
      'bank_name', v_prof.payout_details->>'bank_name',
      'last4', right(coalesce(v_prof.payout_details->>'account', v_prof.payout_details->>'iban', v_prof.payout_details->>'email', ''), 4),
      'docs_ok', (v_prof.payout_details ? 'id_doc') and (v_prof.payout_details ? 'bank_doc'),
      'verified', v_prof.status = 'approved') end,
    'requests', coalesce((select jsonb_agg(jsonb_build_object(
        'id', r.id, 'amount', r.amount, 'status', r.status, 'note', r.note,
        'requested_at', r.requested_at, 'decided_at', r.decided_at,
        'bank_name', r.payout_details->>'bank_name',
        'last4', right(coalesce(r.payout_details->>'account', r.payout_details->>'iban', r.payout_details->>'email', ''), 4)
      ) order by r.requested_at desc)
      from app_private.referral_payout_requests r where r.referrer_id = v_ref.id), '[]'::jsonb));
end; $function$

CREATE OR REPLACE FUNCTION public.agent_request_payout()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'app_private, public'
AS $function$
declare v_ref app_private.referrers; v_prof app_private.agent_profiles; v_payable numeric; v_id uuid; v_email text;
begin
  perform app_private.assert_payment_session();
  v_ref := app_private.agent_referrer_for(auth.uid());
  if v_ref.id is null then raise exception 'no agent account' using errcode='42501'; end if;
  select * into v_prof from app_private.agent_profiles where user_id = auth.uid();
  if v_prof.status is distinct from 'approved' then raise exception 'verification incomplete — payouts unlock after approval' using errcode='22023'; end if;
  if coalesce(v_prof.payout_method,'') = '' then raise exception 'no payout account on file — add it in Get Verified' using errcode='22023'; end if;
  select coalesce(sum(amount) filter (where status = 'payable'), 0) into v_payable
    from app_private.referral_commissions where referrer_id = v_ref.id;
  if v_payable < 100 then raise exception 'payable balance $% is below the $100 minimum', v_payable using errcode='22023'; end if;
  if exists (select 1 from app_private.referral_payout_requests r where r.referrer_id = v_ref.id and r.status in ('requested','approved')) then
    raise exception 'a payout request is already in progress' using errcode='22023';
  end if;
  insert into app_private.referral_payout_requests (referrer_id, requested_by, amount, payout_details, status)
  values (v_ref.id, auth.uid(), v_payable,
          coalesce(v_prof.payout_details, '{}'::jsonb) || jsonb_build_object('method', v_prof.payout_method, 'account_title', coalesce(v_prof.payout_details->>'account_title', v_prof.full_name)),
          'requested')
  returning id into v_id;
  begin
    insert into app_private.notifications(recipient_role, channel, template_key, payload)
    values ('staff', 'in_app', 'agent.payout_requested',
      jsonb_build_object('title', '💸 Agent payout requested', 'body', coalesce(v_prof.full_name,'Agent') || ' — $' || v_payable || ' to ' || v_prof.payout_method, 'request', v_id));
  exception when others then null; end;
  begin
    insert into app_private.notifications(recipient_user, channel, template_key, payload, status, sent_at)
    values (auth.uid(), 'in_app', 'agent.payout_requested_self', jsonb_build_object(
      'title', '💸 Payout request received — $' || v_payable,
      'body', 'A person reviews it, then the transfer goes out to your ' || v_prof.payout_method || ' account. Bank transfers typically land 3–5 business days after SENT. Track it in Payouts.',
      'tone', 'info', 'url', '/app/agent/#payouts'), 'sent', now());
  exception when others then null; end;
  begin
    select email into v_email from auth.users where id = auth.uid();
    if v_email is not null then
      perform app_private.sys_email(v_email, 'agent.payout_requested_self', 'LoadBoot: payout request received — $' || v_payable,
        '<div style="font-family:Inter,Arial,sans-serif"><h2>💸 Your payout request is in</h2>'
        || '<p><b>$' || v_payable || '</b> → your ' || v_prof.payout_method || ' account. A person reviews every payout, then the transfer goes out. '
        || 'Bank transfers typically land <b>3–5 business days after SENT</b>.</p>'
        || '<p>Track every step: <a href="https://loadboot.com/app/agent/#payouts">Payout Center</a></p></div>',
        null, 'agentpayoutreq:' || v_id::text);
    end if;
  exception when others then null; end;
  return jsonb_build_object('ok', true, 'id', v_id, 'amount', v_payable,
    'note', 'Payout requested — a person reviews it, then the transfer goes out. Bank transfers typically land in 3–5 business days after SENT.');
end; $function$

CREATE OR REPLACE FUNCTION public.cc_my_payout_requests()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'app_private, public'
AS $function$
declare v_uid uuid; v_ref uuid;
begin
  perform app_private.assert_payment_session();
  v_uid := auth.uid(); if v_uid is null then raise exception 'not authenticated' using errcode='42501'; end if;
  select id into v_ref from app_private.referrers where user_id = v_uid;
  if v_ref is null then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'id', r.id, 'amount', r.amount, 'status', r.status, 'note', r.note,
      'requested_at', r.requested_at, 'decided_at', r.decided_at,
      'bank_name', r.payout_details->>'bank_name',
      'account_last4', right(coalesce(r.payout_details->>'account_number',''), 4)
    ) order by r.requested_at desc)
    from app_private.referral_payout_requests r where r.referrer_id = v_ref), '[]'::jsonb);
end; $function$

CREATE OR REPLACE FUNCTION public.cc_referral_request_payout(p_details jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'app_private, public'
AS $function$
declare v_uid uuid; v_ref app_private.referrers; v_bal numeric; v_id uuid;
begin
  perform app_private.assert_payment_session();
  v_uid := auth.uid(); if v_uid is null then raise exception 'not authenticated' using errcode='42501'; end if;
  select * into v_ref from app_private.referrers where user_id = v_uid;
  if v_ref.id is null then raise exception 'join the referral program first' using errcode='22023'; end if;
  if coalesce(trim(p_details->>'account_title'),'') = '' or coalesce(trim(p_details->>'bank_name'),'') = ''
     or coalesce(trim(p_details->>'account_number'),'') = '' then
    raise exception 'bank_name, account_title and account_number are required' using errcode='22023';
  end if;
  select coalesce(sum(amount),0) into v_bal from app_private.referral_commissions
    where referrer_id = v_ref.id and status = 'payable';
  if v_bal <= 0 then raise exception 'no payable balance yet — commissions clear a 15-day hold first' using errcode='22023'; end if;
  if exists (select 1 from app_private.referral_payout_requests
             where referrer_id = v_ref.id and status in ('requested','approved')) then
    raise exception 'you already have an open payout request' using errcode='22023';
  end if;
  insert into app_private.referral_payout_requests(referrer_id, requested_by, amount, payout_details)
    values (v_ref.id, v_uid, v_bal, jsonb_build_object(
      'bank_name', trim(p_details->>'bank_name'),
      'account_title', trim(p_details->>'account_title'),
      'account_number', trim(p_details->>'account_number')))
    returning id into v_id;
  perform app_private.log_audit('referral.payout_requested','payout_request',v_id::text,null,
    format('payout of $%s requested', v_bal), null);
  return jsonb_build_object('ok',true,'id',v_id,'amount',v_bal,'status','requested',
    'note','a person reviews every payout; money moves through the normal payment rail');
end; $function$

